import {useQuery} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'

export type AgenticAutofixState = 'unassigned' | 'pending' | 'completed' | 'failed'

export type CopilotPullRequest = {
  number: number
  createdAt: string
}

export type AgenticAutofixStatusResponse = {
  state: AgenticAutofixState
  copilotPullRequest?: CopilotPullRequest | null
  errorMessage?: string | null
}

export function agenticAutofixStatusQueryKey(url: string) {
  return ['code-scanning-agentic-autofix-status', url]
}

export function useAgenticAutofixStatusQuery(url: string, initialData: AgenticAutofixStatusResponse) {
  return useQuery<AgenticAutofixStatusResponse>({
    queryKey: agenticAutofixStatusQueryKey(url),
    queryFn: async () => {
      const response = await reactFetchJSON(url)
      if (!response.ok) throw new Error(`Failed to fetch status: ${response.status}`)
      return response.json()
    },
    initialData,
    enabled: false,
  })
}
