import {Button, Label, Link, RelativeTime, Spinner} from '@primer/react'
import {AgentIcon, CopilotIcon, StopIcon} from '@primer/octicons-react'
import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'
import {
  codeScanningGenerateAutofixPath,
  codeScanningAgenticAutofixStatusPath,
  pullRequestTitlePath,
} from '@github-ui/paths'
import {useAlive} from '@github-ui/use-alive'
import {useQueryClient} from '@github-ui/react-query'
import {useAssignToCopilotMutation} from '@github-ui/code-scanning-shared/hooks/use-assign-to-copilot-mutation'
import {useAgenticAutofixStatusQuery, agenticAutofixStatusQueryKey} from './hooks/use-agentic-autofix-status-query'
import type {
  AgenticAutofixState,
  AgenticAutofixStatusResponse,
  CopilotPullRequest,
} from './hooks/use-agentic-autofix-status-query'
import {useAgenticAutofixJobPoll} from '@github-ui/code-scanning-shared/hooks/use-agentic-autofix-job-poll'
import {AgenticAutofixError} from '@github-ui/code-scanning-shared/types/agentic-autofix-error'
import {displayFlashMessage} from '@github-ui/code-scanning-shared/utils/display-flash-message'
import {useCallback, useEffect, useState} from 'react'
import {clsx} from 'clsx'
import {
  onAgenticAutofixError,
  onAgenticAutofixStarted,
} from '@github-ui/code-scanning-assignees-section/agentic-autofix-event'
import {AgenticAutofixErrorBanner} from '@github-ui/code-scanning-shared/components/AgenticAutofixErrorBanner'
import styles from './CodeScanningAgenticAutofixBanner.module.css'

export type CodeScanningAgenticAutofixBannerProps = {
  state: AgenticAutofixState
  autofixDocsUrl: string
  autofixToolName: string
  alertNumber: number
  repository: {owner: string; name: string}
  aliveChannel?: string
  copilotPullRequest?: CopilotPullRequest | null
  errorMessage?: string | null
}

export function CodeScanningAgenticAutofixBanner({
  state: initialState,
  autofixDocsUrl,
  autofixToolName,
  alertNumber,
  repository,
  aliveChannel,
  copilotPullRequest: initialCopilotPullRequest,
  errorMessage: initialErrorMessage,
}: CodeScanningAgenticAutofixBannerProps) {
  const getHovercardAttributesForType = useGetHovercardAttributesForType()
  const queryClient = useQueryClient()

  const generateAutofixUrl = codeScanningGenerateAutofixPath({
    owner: repository.owner,
    repo: repository.name,
    alertNumber,
  })

  const agenticAutofixStatusUrl = codeScanningAgenticAutofixStatusPath({
    owner: repository.owner,
    repo: repository.name,
    alertNumber,
  })

  const queryKey = agenticAutofixStatusQueryKey(agenticAutofixStatusUrl)

  const {data: bannerStatus, refetch} = useAgenticAutofixStatusQuery(agenticAutofixStatusUrl, {
    state: initialState,
    copilotPullRequest: initialCopilotPullRequest ?? null,
    errorMessage: initialErrorMessage ?? null,
  })

  const {state, copilotPullRequest, errorMessage: statusErrorMessage} = bannerStatus

  const [jobId, setJobId] = useState<string | null>(null)
  const [agenticAutofixError, setAgenticAutofixError] = useState<AgenticAutofixError | null>(null)

  useEffect(
    () =>
      onAgenticAutofixStarted(job => {
        setJobId(job.jobId)
        setAgenticAutofixError(null)
        queryClient.setQueryData<AgenticAutofixStatusResponse>(queryKey, prev =>
          prev
            ? {...prev, state: 'pending', errorMessage: null}
            : {state: 'pending', copilotPullRequest: null, errorMessage: null},
        )
      }),
    [queryClient, queryKey],
  )
  useEffect(
    () =>
      onAgenticAutofixError(error => {
        setAgenticAutofixError(error)
      }),
    [],
  )

  const {errorMessage: pollErrorMessage} = useAgenticAutofixJobPoll(repository.owner, repository.name, jobId)

  // Use error from CAPI polling, or from status endpoint if available
  const errorMessage = pollErrorMessage || statusErrorMessage || null

  const {mutate: mutateAssignToCopilot, isPending} = useAssignToCopilotMutation(generateAutofixUrl)

  const handleAssignToCopilotClick = () => {
    setAgenticAutofixError(null)
    mutateAssignToCopilot(undefined, {
      onSuccess: data => {
        if (data.jobId) {
          setJobId(data.jobId)
        }
        queryClient.setQueryData<AgenticAutofixStatusResponse>(queryKey, prev =>
          prev
            ? {...prev, state: 'pending', errorMessage: null}
            : {state: 'pending', copilotPullRequest: null, errorMessage: null},
        )
        displayFlashMessage(
          'success',
          'Successfully assigned to Copilot to generate a fix. Copilot will open a pull request.',
        )
      },
      onError: error => {
        if (error instanceof AgenticAutofixError) {
          setAgenticAutofixError(error)
          return
        }

        displayFlashMessage('error', 'Failed to assign to Copilot. Please try again.')
      },
    })
  }

  const handleAliveMessage = useCallback(() => {
    refetch()
  }, [refetch])

  useAlive(aliveChannel, handleAliveMessage)

  const isFailed = state === 'failed' || (state === 'pending' && !!errorMessage)
  const isLoading = state === 'pending' && !errorMessage

  const pullRequestUrl = copilotPullRequest
    ? pullRequestTitlePath({
        owner: repository.owner,
        repo: repository.name,
        number: copilotPullRequest.number,
      })
    : undefined

  const hovercardAttrs = copilotPullRequest
    ? getHovercardAttributesForType('pull_request', {
        owner: repository.owner,
        repo: repository.name,
        pullRequestNumber: copilotPullRequest.number,
      })
    : {}

  if (agenticAutofixError) {
    return (
      <AgenticAutofixErrorBanner
        error={agenticAutofixError}
        repository={repository}
        onRetry={handleAssignToCopilotClick}
        onDismiss={() => setAgenticAutofixError(null)}
      />
    )
  }

  return (
    <div className={clsx(styles.Banner, isFailed && styles.errorBanner)} role="status">
      <div className={clsx(styles.IconContainer, isLoading && styles.loading, isFailed && styles.errorIcon)}>
        {isLoading && (
          <div className={styles.SpinnerOverlay}>
            <Spinner size="medium" />
          </div>
        )}
        {isFailed ? <StopIcon size={16} /> : <CopilotIcon size={16} />}
      </div>

      <div className={styles.Content}>
        {state === 'unassigned' && (
          <p className={styles.ContentText}>
            Speed up the remediation of this alert with{' '}
            <Link href={autofixDocsUrl} inline>
              {autofixToolName}
            </Link>
          </p>
        )}
        {isLoading && (
          <p className={styles.ContentText}>
            <strong>Copilot Autofix</strong> <Label variant="secondary">AI</Label>{' '}
            <span className="color-fg-muted">is creating a pull request&hellip;</span>
          </p>
        )}
        {state === 'completed' && pullRequestUrl && (
          <p className={styles.ContentText}>
            <strong>Copilot Autofix</strong> <Label variant="secondary">AI</Label>{' '}
            <span className="color-fg-muted">
              <Link href={pullRequestUrl} inline {...hovercardAttrs}>
                created a pull request
              </Link>{' '}
              {copilotPullRequest?.createdAt && <RelativeTime datetime={copilotPullRequest.createdAt} tense="past" />}
            </span>
          </p>
        )}
        {isFailed && (
          <p className={styles.ContentText}>
            <strong>Copilot Autofix</strong> <Label variant="secondary">AI</Label>{' '}
            <span className="color-fg-muted">{`Failed to create pull request${errorMessage ? `: ${errorMessage}.` : '.'}`}</span>
          </p>
        )}
      </div>

      {state === 'unassigned' && (
        <Button onClick={handleAssignToCopilotClick} loading={isPending} disabled={isPending} leadingVisual={AgentIcon}>
          Assign to Copilot
        </Button>
      )}
    </div>
  )
}
